#!/usr/bin/env python3
"""Supplementary tables of the controlled study, converted from the auto-generated TABLES_*.md files.
Usage: python3 scripts/make_supp_tables_v3.py   (from the manuscript root). No number is typed by hand."""
import os, re, json
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
D = os.path.join(ROOT, "data33_17"); T = os.path.join(ROOT, "tables")
HEAD = "% generated by scripts/make_supp_tables_v3.py from data33_17 -- do not edit by hand\n"
TR = {"合并": "Pooled", "五集合并": "Pooled", "等权平均": "Mean", "全部": "all", "不变": "unchanged", "成立": "holds", "不成立": "fails",
      "correct": "Correct", "selection_failure": "Selection failure", "pose_failure": "Pose failure",
      "recognition_missing": "Missed recognition", "segmentation_missing": "Missed segmentation",
      "Y3Base": "Base pool", "ECA": "A", "ECB": "B", "ECC": "C", "ECD": "D", "ECE": "E"}


def md_table(fname, title):
    rows, on = [], False
    for line in open(os.path.join(D, fname), encoding="utf8"):
        if line.startswith("## "):
            on = line[3:].strip() == title; continue
        if on and line.startswith("|") and not line.startswith("| ---"):
            rows.append([c.strip() for c in line.strip().strip("|").split("|")])
    assert rows, (fname, title)
    return rows[1:]


def cell(c):
    c = TR.get(c, c)
    c = c.replace("%", "\\%").replace("—", "--").replace("_", "\\_").replace("≥", "$\\geq$").replace("–", "--").replace("<", "$<$").replace(">", "$>$")
    c = re.sub(r"(?<![\w.])-(\d)", r"$-$\1", c)
    return c


def write(name, header, rows, align=None, keep=None, rowmap=None):
    if keep is not None: rows = [[r[i] for i in keep] for r in rows]
    if rowmap: rows = [rowmap(r) for r in rows]; rows = [r for r in rows if r is not None]
    align = align or ("l" + "c" * (len(header) - 1))
    out = [HEAD, f"\\begin{{tabular}}{{{align}}}\n\\toprule\n", " & ".join(header) + " \\\\\n\\midrule\n"]
    for r in rows: out.append(" & ".join(cell(c) for c in r) + " \\\\\n")
    out.append("\\bottomrule\n\\end{tabular}\n")
    open(os.path.join(T, name), "w").write("".join(out))


if __name__ == "__main__":
    os.makedirs(T, exist_ok=True)
    P1, P2 = "TABLES_P1.md", "TABLES_P2.md"
    write("supp_repro.tex", ["Ranking score", "Earlier development run", "Controlled study $-$ earlier"],
          [[{"A1": "Per-call score", "A2": "Detector confidence", "A3": "Depth consistency", "A4": "Joint score"}[r[0]], r[1], r[2]] for r in md_table(P1, "A1–A4 与论文表 7")], align="lcc")
    write("supp_megapose_pairs.tex", ["Dataset", "Median", "99th pct.", "Max", "Targets with changed order"], md_table(P1, "A5 与 A5j 的逐位姿对比"), keep=[0, 1, 2, 3, 4], align="lcccc",
          rowmap=lambda r: [r[0]] + [f"{float(x):.3f}" for x in r[1:4]] + [r[4]])
    write("supp_stability.tex", ["Dataset", "Targets", "Removals", "Selected set changes (\\%)", "Correct count: more", "same", "fewer"], md_table(P1, "X3 去掉未选候选（%）"), align="lcccccc")
    write("supp_convergence.tex", ["Dataset", "Calls", "Spearman $\\rho$ [95\\% CI]", "Correct (\\%)", "Incorrect (\\%)", "AUC"], md_table(P2, "Y6 收敛度与原始分数"), align="lrcccc",
          rowmap=lambda r: [r[0], f"{int(r[1]):,}", r[2], r[3].split(" ")[0], r[4].split(" ")[0], r[5]])
    write("supp_convergence_pairs.tex", ["Dataset", "Difference in share", "Pairs", "Per-call score correct (\\%)", "Correct pose has larger share (\\%)"],
          [r for r in md_table(P2, "Y6 组内成对排序") if r[0] == "合并"], align="llrcc", rowmap=lambda r: [r[0], r[1], f"{int(r[2]):,}", r[3], r[4]])
    for ds, f, t in (("ipd", P1, "IPD 失败五分类"), ("xyz", P2, "Y1 五类失败")):
        write(f"supp_failure_{ds}.tex", ["Class", "B1 instances", "B1 loss", "B4 instances", "B4 loss"], md_table(f, t), align="lrrrr")
    write("supp_ec.tex", ["Pool", "AR", "VSD", "MSSD", "MSPD"], md_table(P1, "EC 评测"), align="lcccc")
    names = {"Low": "Lower-ranked 2D", "S": "SAM2 masks", "G": "Depth--normal segments", "Mix": "2D + segments"}
    def y3(r):
        m = re.match(r"Y3(Low|S|G|Mix)(\d)", r[0])
        return [("Base pool" if not m else names[m.group(1)]), ("0" if not m else m.group(2))] + r[1:]
    for ds in ("IC-BIN", "IPD", "XYZ-IBD"):
        write(f"supp_slots_{ds.lower().replace('-', '')}.tex", ["Source", "$k$", "AR" if ds == "IC-BIN" else "AP", "Instance recall (\\%)", "Added registrations per frame"],
              md_table(P2, f"Y3 {ds}"), align="lcccc", rowmap=y3)
    def y4(r):
        m = re.match(r"Y4(B\d)(?:T(\d+))?", r[0]); thr = m.group(2)
        return [m.group(1), ("official (0.20)" if thr in (None, "20") else f"0.{int(thr):02d}")] + r[1:]
    for ds in ("IPD", "XYZ-IBD"):
        write(f"supp_threshold_{ds.lower().replace('-', '')}.tex", ["Row", "Threshold", "AP", "Instance recall (\\%)", "Outputs per frame"], md_table(P2, f"Y4 {ds}"), align="llccc", rowmap=y4)
        rows = [r for r in md_table(P2, f"Y7 {ds} 输出构成") if r[0] in ("B0", "B1", "B3", "B4")]
        write(f"supp_outputs_{ds.lower().replace('-', '')}.tex", ["Row", "Source", "Correct", "Duplicate", "Wrong pose", "Wrong object", "Background"], rows, align="llccccc",
              rowmap=lambda r: None if (r[0] in ("B0", "B1") and r[1] != "全部") else r)
    for task, key in (("localization", "Y2 localization"), ("detection", "Y2 detection")):
        write(f"supp_density_{task}.tex", ["Density", "Frames", "Missed-segmentation share", "Coverage gain (per-call basis)" if task == "localization" else "Coverage gain", "Gain of joint over per-call" if task == "localization" else "B4 $-$ B0"],
              md_table(P2, key), align="lrccc")
    d = json.load(open(os.path.join(D, "derived_v3.json")))["density_A4_basis_posthoc"]
    rows = [[b, str(n), f"{m:.2f} [{c[0]:.2f}, {c[1]:.2f}]", f"{w:.2f}"] for b, n, m, c, w in zip(d["bins"], d["frames"], d["A4_mean"], d["A4_ci"], d["A4_instance_weighted"])]
    write("supp_density_posthoc.tex", ["Density", "Frames", "Coverage gain, joint basis (frame mean)", "Instance-weighted"], rows, align="lrcc")
    ss = json.load(open(os.path.join(D, "SETSENS.json")))["scopes"]
    nm = {"lmo": "LM-O", "tless": "T-LESS", "tudl": "TUD-L", "icbin": "IC-BIN", "ycbv": "YCB-V", "pooled": "Pooled"}
    rows = []
    for k in ("lmo", "tless", "tudl", "icbin", "ycbv", "pooled"):
        for sc, lab in (("FP", "FP"), ("MegaPose", "MP")):
            v = ss[k][sc]; nd = v["normalized_abs_delta"]; kt = v["kendall_tau"]
            rows.append([nm[k] if sc == "FP" else "", lab, f"{v['solo_scores_iqr']:.2f}", f"{nd['median']:.3f}", f"{nd['p90']:.3f}", f"{nd['max']:.3f}",
                         f"{v['targets_at_least_two']:,}", f"{kt['median']:+.2f} [{kt['q1']:+.2f}, {kt['q3']:+.2f}]", f"{v['winner_changed']:,}", f"{v['solo_correct_top']:,} / {v['joint_correct_top']:,}"])
    write("supp_setsens.tex", ["Dataset", "Scorer", "IQR", "Change: median", "P90", "Max", "Targets", "Kendall $\\tau$", "Top changes", "Correct top: own / joint"], rows, align="llrrrrrcrc")
    Y8 = "TABLES_Y8.md"
    write("supp_y8_pairs.tex", ["Dataset", "Pairs", "MP $z$", "MP softmax", "MP margin", "FP $z$", "FP softmax", "FP margin"],
          md_table(Y8, "K=16 跨调用成对准确率（%）"), align="lrcccccc", rowmap=lambda r: [r[0], f"{int(r[1]):,}"] + [x.split(" ")[0] for x in r[2:]])
    k = [r for r in md_table(Y8, "同一批胜者对的 K=16 与 K=252 准确率（%）") if r[0] in ("合并", "五集合并")]
    nz = {r[0]: r for r in md_table(Y8, "v1.1 的批次噪声底线")}
    nm8 = {"A12": "MegaPose $z$-score", "A13": "MegaPose softmax", "A14": "MegaPose margin"}
    write("supp_y8_k.tex", ["Relative score", "Batch noise (pp)", "Bounds: inverts / does not", "$K=16$ (\\%)", "$K=252$ (\\%)", "Difference (pp)"],
          [[nm8[r[1]], nz[r[1]][3], f"below {nz[r[1]][5]} / at least {nz[r[1]][6]}", r[2], r[3], r[4]] for r in k], align="lccccc")
    print("ok")
